package app.safevault.crypto

import java.security.GeneralSecurityException
import java.security.Key
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec

/** Outer, device-bound layer around the serialized vault header. */
interface HeaderProtector {
    fun protect(plain: ByteArray): ByteArray

    /** @throws DeviceKeyUnavailableException if the device key cannot authenticate the blob. */
    fun unprotect(blob: ByteArray): ByteArray
}

/**
 * AES-256-GCM under a [Key] from [keySource]. Layout: version(1) | iv(12) | ciphertext||tag.
 * The IV is generated by the provider (required by AndroidKeyStore; random in the JDK), never supplied.
 * Works with software keys (tests) and non-extractable AndroidKeyStore keys (production).
 */
class KeyHeaderProtector(
    private val keySource: () -> Key,
    private val aad: ByteArray = "SafeVault/header/v1".toByteArray(),
) : HeaderProtector {

    override fun protect(plain: ByteArray): ByteArray {
        val c = Cipher.getInstance(TRANSFORMATION)
        c.init(Cipher.ENCRYPT_MODE, keySource())
        c.updateAAD(aad)
        val ct = c.doFinal(plain)
        val iv = c.iv
        check(iv != null && iv.size == IV_SIZE) { "Unexpected IV" }
        return byteArrayOf(VERSION) + iv + ct
    }

    override fun unprotect(blob: ByteArray): ByteArray {
        if (blob.size < 1 + IV_SIZE + AesGcm.TAG_SIZE || blob[0] != VERSION) throw DeviceKeyUnavailableException()
        try {
            val c = Cipher.getInstance(TRANSFORMATION)
            c.init(Cipher.DECRYPT_MODE, keySource(), GCMParameterSpec(AesGcm.TAG_SIZE * 8, blob, 1, IV_SIZE))
            c.updateAAD(aad)
            return c.doFinal(blob, 1 + IV_SIZE, blob.size - 1 - IV_SIZE)
        } catch (e: GeneralSecurityException) {
            throw DeviceKeyUnavailableException()
        }
    }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val IV_SIZE = 12
        const val VERSION: Byte = 1
    }
}
